        num.to_string()
            .chars()
            .filter(|&c| c != '0')
            .filter(|&c| num % (c.to_digit(10).unwrap() as i32) == 0)
            .count() as i32
    }
}

class Solution {
public:
    int countDigits(int num) {
        int numcp = num;
        int count = 0;
        while(numcp > 0){
            if(num % (numcp % 10) == 0)
                count++;
            numcp /= 10;
        }
        return count;
    }
};

